import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const P=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-PCOMPUTE.md","filePath":"manual-zh/CTABLES-PCOMPUTE.md","lastUpdated":1785684581000}'),c={name:"manual-zh/CTABLES-PCOMPUTE.md"};function a(p,t,T,_,n,E){return e(),r("div",null,[...t[0]||(t[0]=[o(`<h4 id="_15-7-10-1-pcompute" tabindex="-1">15.7.10.1 PCOMPUTE <a class="header-anchor" href="#_15-7-10-1-pcompute" aria-label="Permalink to &quot;15.7.10.1 PCOMPUTE&quot;">​</a></h4><pre><code>/PCOMPUTE &amp;_postcompute_ =EXPR(_expression_)
</code></pre><p><code>PCOMPUTE</code> 子命令必须位于第一个 <code>TABLE</code> 命令之前，用于定义计算类别。它是可选的，可使用任意多次以定义多个后计算。</p><p>每个 <code>PCOMPUTE</code> 定义一个后计算。其语法由一个用于标识后计算的名称（作为以 ‘&amp;’ 为前缀的 PSPP 标识符）、后接 ‘=’ 以及括在 <code>EXPR(…)</code> 中的后计算表达式组成。后计算表达式包含：</p><p><code>[_category_]</code></p><p>这种形式求值为 <em>category</em> 的汇总统计量，例如 <code>[1]</code> 求值为与类别 1 关联的汇总统计量的值。<em>category</em> 可以是一个数字、带引号的字符串，或带引号的日期或时间值。给定后计算的所有类别必须具有相同的形式。该类别必须出现在使用此后计算的所有 <code>CATEGORIES</code> 列表中。</p><p><code>[_min_ THRU _max_]</code><code>[LO THRU _max_]</code><code>[_min_ THRU HI]</code><code>MISSING</code><code>OTHERNM</code></p><p>这些形式求值为用相同语法指定的类别的汇总统计量，如前文所述（参见 <a href="./CTABLES-Explicit-Categories#CTABLES-Explicit-Category-List">CTABLES Explicit Category List</a>）。该类别必须出现在使用此后计算的所有 <code>CATEGORIES</code> 列表中。</p><p><code>SUBTOTAL</code></p><p>小计类别的汇总统计量。仅当包含此后计算的 <code>CATEGORIES</code> 列表恰好只有一个小计时，才允许使用这种形式。</p><p><code>SUBTOTAL[_index_]</code></p><p>小计类别 <em>index</em> 的汇总统计量，其中 1 为第一个小计，2 为第二个，依此类推。这种形式可用于具有任意数量小计的 <code>CATEGORIES</code> 列表。</p><p><code>TOTAL</code></p><p>总计的汇总统计量。包含此后计算的 <code>CATEGORIES</code> 列表必须启用了总计。</p><p><code>_a_ + _b_</code><code>_a_ - _b_</code><code>_a_ * _b_</code><code>_a_ / _b_</code><code>_a_ ** _b_</code></p><p>这些形式对后计算表达式 <em>a</em> 和 <em>b</em> 的值执行算术运算。适用通常的运算符优先级规则。</p><p><code>_number_</code></p><p>后计算表达式中可以使用数值常量。</p><p><code>(_a_)</code></p><p>括号可覆盖运算符优先级。</p><p>后计算不与任何特定变量关联。相反，它可以在任何合适变量的 <code>CATEGORIES</code> 中被引用（例如，只有字符串变量才适合引用字符串类别的后计算表达式，只有带小计的变量才适合引用小计的表达式，……）。</p><p>通常一个具名后计算只定义一次，但如果后面的 <code>PCOMPUTE</code> 用与前面相同的名称重新定义了某个后计算，则以后面的为准。</p><p>以下语法和输出展示了 <code>PCOMPUTE</code> 如何计算小计之上的总计，将“Frequent Drivers”和“Infrequent Drivers”两个小计相加，形成“All Drivers”后计算。它还展示了如何计算并显示一个百分比，此处为报告从未驾驶的有效回答的百分比。它使用 <code>PPROPERTIES</code>（参见 <a href="./CTABLES-PPROPERTIES">CTABLES PPROPERTIES</a>）以 <code>PCT</code> 格式显示后者。</p><pre><code>CTABLES
    /PCOMPUTE &amp;all_drivers=EXPR([1 THRU 2] + [3 THRU 4])
    /PPROPERTIES &amp;all_drivers LABEL=&#39;All Drivers&#39;
    /PCOMPUTE &amp;pct_never=EXPR([5] / ([1 THRU 2] + [3 THRU 4] + [5]) * 100)
    /PPROPERTIES &amp;pct_never LABEL=&#39;% Not Drivers&#39; FORMAT=COUNT PCT40.1
    /TABLE=freqOfDriving BY gender
    /CATEGORIES VARIABLES=freqOfDriving
                             [1 THRU 2, SUBTOTAL=&#39;Frequent Drivers&#39;,
                              3 THRU 4, SUBTOTAL=&#39;Infrequent Drivers&#39;,
                              &amp;all_drivers, 5, &amp;pct_never,
                              MISSING, SUBTOTAL=&#39;Not Drivers or Missing&#39;].
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td></td><td></td><td>Count</td><td>Count</td></tr><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>2305</td><td>2362</td></tr><tr><td>Several days a week</td><td>440</td><td>834</td><td></td></tr><tr><td>Frequent Drivers</td><td>2745</td><td>3196</td><td></td></tr><tr><td>Once a week or less</td><td>125</td><td>236</td><td></td></tr><tr><td>Only certain times a year</td><td>58</td><td>72</td><td></td></tr><tr><td>Infrequent Drivers</td><td>183</td><td>308</td><td></td></tr><tr><td>All Drivers</td><td>2928</td><td>3504</td><td></td></tr><tr><td>Never</td><td>192</td><td>348</td><td></td></tr><tr><td>% Not Drivers</td><td>6.2%</td><td>9.0%</td><td></td></tr><tr><td>Don&#39;t know</td><td>3</td><td>5</td><td></td></tr><tr><td>Refused</td><td>9</td><td>10</td><td></td></tr><tr><td>Not Drivers or Missing</td><td>204</td><td>363</td><td></td></tr></tbody></table>`,25)])])}const s=d(c,[["render",a]]);export{P as __pageData,s as default};
